    playerFloat: exp("isaac_room_transition_engine_82ee40_player_entry_float_reset"),
    pred82eb90: exp("isaac_room_transition_engine_82eb90_predicate"),
    playerLoopNeedsHost: exp("isaac_room_transition_engine_player_loop_needs_host"),
    playerCount: exp("isaac_room_transition_engine_82ee40_player_count"),
    playerLoopEnter: exp("isaac_room_transition_engine_82ee40_player_loop_enter"),
    playerLoopStep: exp("isaac_room_transition_engine_82ee40_player_loop_step"),
    playerLoopContinue: exp("isaac_room_transition_engine_82ee40_player_loop_continue"),
    playerEntryEligible: exp("isaac_room_transition_engine_82ee40_player_entry_eligible"),
    call7abcc0Needed: exp("isaac_room_transition_engine_82ee40_7abcc0_needed"),
    call7abcc0Arg: exp("isaac_room_transition_engine_82ee40_7abcc0_arg"),
    call7abe20Needed: exp("isaac_room_transition_engine_82ee40_7abe20_needed"),
    callPlan: exp("isaac_room_transition_engine_82ee40_player_call_plan"),
    rewindNeeded: exp("isaac_room_transition_engine_7abe20_rewind_needed"),
    rewindDecision: exp("isaac_room_transition_engine_7abe20_rewind_decision"),
    storePlan: exp("isaac_room_transition_engine_7abe20_store_plan"),
    param2: exp("isaac_room_transition_engine_7abcc0_param2"),
    sfxNeeded: exp("isaac_room_transition_engine_7abcc0_sfx_needed"),
    wrapperPlan: exp("isaac_room_transition_engine_7abcc0_plan"),
    sfxPack: exp("isaac_room_transition_engine_sfx_play_pack"),
    // ---- v7 ----
    c7b640Bits: exp("isaac_room_transition_engine_c7b640_bits"),
    c7b644Bits: exp("isaac_room_transition_engine_c7b644_bits"),
    loopEndUsed: exp("isaac_room_transition_engine_82ee40_player_loop_end_used"),
