/* ------------------------------------------------------------------------
   Section-table PE reader (v7). AGENTS.md: `VA -> file offset` must come from
   the section headers, and `.data`'s raw size is far below its virtual size,
   so VAs past the raw end are ZERO AT LOAD and are NOT file-backed. This
   reader RAISES on those instead of returning plausible garbage — which is
   exactly the bug that produced the v1..v6 "float constants".
   ------------------------------------------------------------------------ */
const PE_SECTIONS = [
  { name: ".text", va: 0x00401000, vsize: 0x00716134, raw: 0x00000400, rsize: 0x00716200 },
  { name: ".rdata", va: 0x00b18000, vsize: 0x000df948, raw: 0x00716600, rsize: 0x000dfa00 },
  { name: ".data", va: 0x00bf8000, vsize: 0x000a4aa4, raw: 0x007f6000, rsize: 0x00069e00 },
  { name: ".rsrc", va: 0x00c9d000, vsize: 0x00003b20, raw: 0x0085fe00, rsize: 0x00003c00 },
  { name: ".reloc", va: 0x00ca1000, vsize: 0x0005c93c, raw: 0x00863a00, rsize: 0x0005ca00 },
];
let PE_BYTES = null;
function peBytes() {
  if (PE_BYTES === null) PE_BYTES = readFileSync(join(root, "tools", "isaac-ng.unpacked.exe"));
  return PE_BYTES;
}
function peSectionOf(va) {
  return PE_SECTIONS.find((s) => va >= s.va && va < s.va + Math.max(s.vsize, s.rsize)) ?? null;
}
function peFileBacked(va) {
  const s = peSectionOf(va);
  return s !== null && va - s.va < s.rsize;
}
function peRaw(va, n) {
  const s = peSectionOf(va);
  if (s === null) throw new Error(`VA 0x${va.toString(16)} is not in any section`);
  const delta = va - s.va;
  if (delta + n > s.rsize) {
    throw new Error(
      `VA 0x${va.toString(16)} (+${n}) is past the raw end of ${s.name}: ` +
        "zero at load, not file-backed",
    );
  }
  return peBytes().subarray(s.raw + delta, s.raw + delta + n);
}
function peCString(va, maxn = 96) {
  const b = peRaw(va, maxn);
  const end = b.indexOf(0);
  return b.subarray(0, end < 0 ? maxn : end).toString("latin1");
}

/* v8 — the same exact-signature scan scripts/decomp/identify-zhl-address.mjs
   performs, run in-test so the "address-stable name" claim cannot rot. Two
   controls in the v8 PE-truth test prove the scan still discriminates: a
   scan that matches nothing for everything would prove nothing. */
let ZHL_CATALOG = null;
function a5d0ZhlMatches() {
  if (ZHL_CATALOG === null) {
    const dir = join(root, "third_party", "REPENTOGON", "libzhl", "functions");
    ZHL_CATALOG = [];
    for (const entry of readdirSync(dir, { recursive: true, withFileTypes: true })) {
      if (!entry.isFile() || !entry.name.endsWith(".zhl")) continue;
      for (const sig of readZhlSignatures(join(entry.parentPath ?? entry.path, entry.name))) {
        ZHL_CATALOG.push({ decl: sig.declaration, bytes: parseSignature(sig.pattern) });
      }
    }
    assert.ok(ZHL_CATALOG.length > 1000, "ZHL catalog looks empty");
  }
  const buf = peBytes();
  return (va) => {
    const sect = peSectionOf(va);
    assert.ok(sect !== null && va - sect.va < sect.rsize, "VA is not file-backed");
    const off = sect.raw + (va - sect.va);
    return ZHL_CATALOG
      .filter((e) => e.bytes.every((b, i) => b === null || buf[off + i] === b))
      .map((e) => e.decl);
  };
}

function writeI32(view, offset, value) {
  view.setInt32(offset, value | 0, true);
}
function writeF32(view, offset, value) {
  view.setFloat32(offset, Math.fround(value), true);
}
function readI32(view, offset) {
  return view.getInt32(offset, true);
}
function readF32(view, offset) {
  return view.getFloat32(offset, true);
}
function readU8(view, offset) {
  return view.getUint8(offset);
}

// Wasm scratch base. Low linear memory holds the module's own constant/table
// data AND emscripten's 64 KiB shadow stack immediately after it; writes below
// 0x100000 can silently corrupt either (table-driven helpers return garbage
// while arithmetic-only ones keep passing). Corrected standing rule: 1 MiB up.
const MEM = 0x100000;

test("room transition engine pure JS oracle matches recovered control flow", () => {
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);

  assert.equal(roomTransitionEngine82ee40EarlySkipSetup(0, 20), 0);
  assert.equal(roomTransitionEngine82ee40EarlySkipSetup(1, 20), 1);
  assert.equal(roomTransitionEngine82ee40EarlySkipSetup(1, 0xf), 0);
  assert.equal(roomTransitionEngine82ee40EarlySkipSetup(0, 0xf), 0);

  // FUN_0082eb90 pure predicate + player-loop host gate.
  assert.equal(roomTransitionEngine82eb90Predicate(0), 0);
  assert.equal(roomTransitionEngine82eb90Predicate(3), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xc), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xd), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xb), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(20), 0);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(0), 0);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(20), 1); // 7abe20
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(3), 1); // 7abcc0 path

  assert.equal(roomTransitionEngine82ee40NeedsAnm2Load(0), 1);
  assert.equal(roomTransitionEngine82ee40NeedsAnm2Load(1), 0);
  assert.equal(roomTransitionEngine82ee40NeedsAnm2Load(0x100), 1);

  assert.equal(roomTransitionEngine82ee40RewriteSlot(5, 3, 1, 5, 1), -1);
  assert.equal(roomTransitionEngine82ee40RewriteSlot(5, 3, 1, 5, 0), 3);
  assert.equal(roomTransitionEngine82ee40RewriteSlot(4, 3, 1, 5, 1), 3);

  assert.equal(roomTransitionEngine82ee40EffectiveDim(-1, 2), 2);
  assert.equal(roomTransitionEngine82ee40EffectiveDim(0, 2), 0);
  assert.equal(roomTransitionEngine82ee40EffectiveDim(1, 2), 1);

  const setup = roomTransitionEngine82ee40ApplySetup({
    room: 9, slot: -1, anim: 20, effectiveDim: 0,
  });
  assert.deepEqual(setup, {
    field4: 0, field10: -1, field14: 9, field18: 0, field1c: 20,
    field20: 0, field24: 0, field238: 0,
  });

  const startAnim2 = roomTransitionEngine82ee40ApplyStartState(2, 7);
  assert.equal(startAnim2.field0, 1);
  assert.equal(startAnim2.field8, 0x1e);
  assert.equal(startAnim2.fieldC, 0);

  const startNeg1 = roomTransitionEngine82ee40ApplyStartState(20, -1);
  assert.equal(startNeg1.field8, 3);
  const startOther = roomTransitionEngine82ee40ApplyStartState(20, 0);
  assert.equal(startOther.field8, 7);

  assert.equal(roomTransitionEngine82ee40NeedsAnim12Sfx(0x12), 1);
  assert.equal(roomTransitionEngine82ee40NeedsAnim12Sfx(20), 0);
  assert.equal(roomTransitionEngine82ee40Anim12SfxId(1), 0x260);
  assert.equal(roomTransitionEngine82ee40Anim12SfxId(0), 0x261);
  assert.equal(roomTransitionEngine82ee40Anim12SfxId(-1), 0x261);

  const pf = roomTransitionEngine82ee40PlayerEntryFloatReset();
  assert.equal(pf.field410, 0);
  assert.equal(pf.field360, startAnim2.field22c);
  assert.equal(pf.field364, startAnim2.field230);

  // FUN_0082eb90: field_1c in {3, 0xc, 0xd, 0xb}.
  assert.equal(roomTransitionEngine82eb90Predicate(0), 0);
  assert.equal(roomTransitionEngine82eb90Predicate(20), 0);
  assert.equal(roomTransitionEngine82eb90Predicate(3), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xc), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xd), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xb), 1);
  assert.equal(roomTransitionEngine82eb90Predicate(0xe), 0);
  // Player-loop host residual: 82eb90 true OR anim==0x14 (7abe20 path).
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(0), 0);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(20), 1);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(3), 1);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(0xb), 1);
  assert.equal(roomTransitionEnginePlayerLoopNeedsHost(1), 0);
});

test("room transition engine pure Wasm matches JS oracle and is zero-import", () => {
  const api = loadExports();
  assert.equal(api.abi(), 30);

  assert.equal(api.earlySkip(1, 20), roomTransitionEngine82ee40EarlySkipSetup(1, 20));
  assert.equal(api.earlySkip(1, 0xf), roomTransitionEngine82ee40EarlySkipSetup(1, 0xf));
  assert.equal(api.earlySkip(0, 3), roomTransitionEngine82ee40EarlySkipSetup(0, 3));

  assert.equal(api.needsAnm2(0), 1);
  assert.equal(api.needsAnm2(2), 0);
  // BYTE GATE (`cmp byte ptr [edi+0x141],0` at 0x0082ee9e): drive the SHIPPED
  // module with WIDE, UNMASKED values. Pre-masking here is exactly the blind
  // spot that hid the uint8_t/-O2 mask-elision defect for 28 ABI versions —
  // and a mutation run proved this export had no wide Wasm-side coverage at
  // all until v7 (the mask-drop mutant SURVIVED).
  for (const v of [0, 1, 0xff, 0x100, 0x1ff, 0x80000000, 0xffffffff, 0x12345600]) {
    assert.equal(
      api.needsAnm2(v) | 0,
      roomTransitionEngine82ee40NeedsAnm2Load(v),
      `needsAnm2 0x${(v >>> 0).toString(16)}`,
    );
  }
  assert.equal(api.needsAnm2(0x100) | 0, 1, "low byte 0 must pass the gate");
  assert.equal(api.needsAnm2(0x1ff) | 0, 0, "low byte 0xff must fail the gate");

  assert.equal(api.rewriteSlot(5, 3, 1, 5, 1), -1);
  assert.equal(api.rewriteSlot(5, 3, 1, 5, 0), 3);
  assert.equal(api.effectiveDim(-1, 9), 9);
  assert.equal(api.effectiveDim(4, 9), 4);

  const view = new DataView(api.memory.buffer);
  // Non-zero, high bases: pointer 0 is nullptr under freestanding C, and low
  // memory belongs to the module (tables + shadow stack).
  const setupBase = MEM + 16;
  for (let i = 0; i < 32; i += 4) writeI32(view, setupBase + i, 0xdeadbeef);
  api.applySetup(setupBase, 9, -1, 20, 0);
  const setupExpected = roomTransitionEngine82ee40ApplySetup({
    room: 9, slot: -1, anim: 20, effectiveDim: 0,
  });
  assert.equal(readI32(view, setupBase + 0), setupExpected.field4);
  assert.equal(readI32(view, setupBase + 4), setupExpected.field10);
  assert.equal(readI32(view, setupBase + 8), setupExpected.field14);
  assert.equal(readI32(view, setupBase + 12), setupExpected.field18);
  assert.equal(readI32(view, setupBase + 16), setupExpected.field1c);
  assert.equal(readI32(view, setupBase + 20), setupExpected.field20);
  assert.equal(readI32(view, setupBase + 24), setupExpected.field24);
  assert.equal(readI32(view, setupBase + 28), setupExpected.field238);

  // Start state scratch
  const base = MEM + 64;
  api.applyStart(base, 2, 7);
  const st2 = roomTransitionEngine82ee40ApplyStartState(2, 7);
  assert.equal(readI32(view, base + 0), st2.field0);
  assert.equal(readI32(view, base + 4), st2.field8);
  assert.equal(readI32(view, base + 8), st2.fieldC);
  assert.equal(readF32(view, base + 12), st2.field22c);
  assert.equal(readF32(view, base + 16), st2.field230);

  api.applyStart(base, 20, -1);
  assert.equal(readI32(view, base + 4), 3);
  api.applyStart(base, 20, 0);
  assert.equal(readI32(view, base + 4), 7);

  assert.equal(api.needsSfx(0x12), 1);
  assert.equal(api.needsSfx(2), 0);
  assert.equal(api.sfxId(1), 0x260);
  assert.equal(api.sfxId(0), 0x261);

  const pfBase = MEM + 128;
  writeF32(view, pfBase, 1);
  writeF32(view, pfBase + 4, 2);
  view.setUint8(pfBase + 8, 9);
  api.playerFloat(pfBase, pfBase + 4, pfBase + 8);
  const pf = roomTransitionEngine82ee40PlayerEntryFloatReset();
  assert.equal(readF32(view, pfBase), pf.field360);
  assert.equal(readF32(view, pfBase + 4), pf.field364);
  assert.equal(readU8(view, pfBase + 8), 0);

  for (const anim of [0, 1, 3, 0xb, 0xc, 0xd, 0xe, 20]) {
    assert.equal(api.pred82eb90(anim), roomTransitionEngine82eb90Predicate(anim));
    assert.equal(
      api.playerLoopNeedsHost(anim),
      roomTransitionEnginePlayerLoopNeedsHost(anim),
    );
  }
});

test("room transition engine pure helpers source is freestanding; dual-gate early-skip Update-wired", () => {
  const hdr = readFileSync(header, "utf8");
  const src = readFileSync(source, "utf8");
  assert.match(hdr, /ISAAC_ROOM_TRANSITION_ENGINE_PURE_HELPERS_ABI_VERSION = 30/);
  assert.match(hdr, /ABI v24 wires sparse dual-gate ownership/);
  // v5: per-entry body pure core. Byte-gate parameters must be uint32_t with
  // an explicit in-body mask (uint8_t params would let -O2 delete the mask —
  // the Wasm ABI never narrows i32 args, so the shipped module would gate on
  // the full word instead of the low byte).
  assert.match(hdr, /ISAAC_ROOM_TRANSITION_ENGINE_HOST_VA_407F10/);
  assert.match(hdr, /ISAAC_ROOM_TRANSITION_ENGINE_HOST_VA_40A1B0/);
  assert.match(hdr, /ISAAC_ROOM_TRANSITION_ENGINE_PARAM2_82F07D/);
  assert.match(src, /a5d0_result_byte & 0xffu/);
  assert.match(src, /uint32_t a5d0_result_byte/);
  // The family stays a pure-helpers island: no 0x0098dba0 re-translation
  // (frame-opaque owns the walk), and the host callees (0x00407f10 ANM2::Reset,
  // 0x00408830, 0x0040a5d0, 0x0040a1b0 Rewind, 0x00956780 PMP prep,
  // 0x0092dc30 Play) must NOT be re-implemented here. The no-call check is
  // applied to the source with comment blocks stripped, so evidence comments
  // that name a callee (e.g. "call 0x00408830 -> entry+0x98") cannot trip it.
  const srcNoComments = src
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/[^\n]*/g, "");
  assert.doesNotMatch(srcNoComments, /0098dba0|0x0098dba0/);
  assert.doesNotMatch(
    srcNoComments,
    /0x00407f10\s*\(|0x00408830\s*\(|0x0040a5d0\s*\(|0x0040a1b0\s*\(|0x00956780\s*\(|0x0092dc30\s*\(/,
  );
  // v7/D1: the C++ must NOT carry the old .reloc-derived bit patterns any
  // more. These two assertions used to pin 0x3760371c / 0x37873770 — a wrong
  // expectation that locked the defect in for six ABI versions.
  const hdrNoComments = hdr
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/[^\n]*/g, "");
  assert.doesNotMatch(srcNoComments, /0x3760371c/);
  assert.doesNotMatch(srcNoComments, /0x37873770/);
  assert.doesNotMatch(hdrNoComments, /0x3760371c/);
  assert.doesNotMatch(hdrNoComments, /0x37873770/);
  assert.match(src, /ISAAC_ROOM_TRANSITION_ENGINE_C7B640_BITS/);
  assert.match(src, /ISAAC_ROOM_TRANSITION_ENGINE_C7B644_BITS/);
  // v6: the wrapper's cmove law and the SFX pack are implemented as pure
  // exports; the prep/play calls themselves stay host (PM/SFX-owned).
  assert.match(hdr, /isaac_room_transition_engine_7abcc0_param2/);
  assert.match(hdr, /isaac_room_transition_engine_sfx_play_pack/);
  assert.match(src, /arg_byte & 0xffu/);
  assert.match(src, /ISAAC_RTE_NO_NARROW_PARAMS\(isaac_room_transition_engine_7abcc0_param2\)/);
  // v8: FUN_0040a5d0 is translated in this TU (the linear search, the inlined
  // strcmp, the arg2 byte gate and the AL-only return). The two remaining
  // host bodies 0x00408830 / 0x00408970 must stay VAs, never re-implemented.
  assert.match(hdr, /isaac_room_transition_engine_40a5d0_lookup/);
  assert.match(hdr, /isaac_room_transition_engine_40a5d0_strcmp/);
  assert.match(hdr, /ISAAC_ROOM_TRANSITION_ENGINE_HOST_VA_408970/);
  assert.match(src, /arg2 & 0xffu/);
  assert.match(src, /ISAAC_RTE_NO_NARROW_PARAMS\(isaac_room_transition_engine_40a5d0_match_callee\)/);
  assert.match(src, /ISAAC_RTE_NO_NARROW_PARAMS\(isaac_room_transition_engine_40a5d0_lookup\)/);
  assert.doesNotMatch(srcNoComments, /0x00408970\s*\(/);
  // Must not pull Game update slice dependencies into the helper TU
  assert.doesNotMatch(src, /game_update_slice/);
  const slice = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  // ABI v29 wires early-skip + apply_setup (mid-engine) + apply_start_state.
  // ABI v35 wires player_entry_float_reset via engine player scratch.
  // ABI v36 wires pure 82eb90 predicate + player_loop_needs_host body gate.
  assert.match(slice, /isaac_room_transition_engine_82ee40_early_skip_setup/);
  assert.match(slice, /isaac_room_transition_engine_82ee40_apply_start_state/);
  assert.match(slice, /isaac_room_transition_engine_82ee40_apply_setup/);
  assert.match(slice, /isaac_room_transition_engine_82ee40_rewrite_slot/);
  assert.match(slice, /isaac_room_transition_engine_82ee40_effective_dim/);
  assert.match(slice, /isaac_room_transition_engine_82ee40_player_entry_float_reset/);
  assert.match(slice, /isaac_room_transition_engine_player_loop_needs_host/);
  assert.match(slice, /engine_player_blob_ready/);

  /* ---- v10: MULTI-LINE-AWARE byte-gate parameter re-census ----
     A single-line grep cannot see a prototype wrapped across lines, and a
     guard that silently matches NOTHING passes vacuously — the exact failure
     that let four uint8_t parameters survive in a family recorded CLEAN. So
     this parses every exported prototype with whitespace collapsed, PROVES it
     saw the parameters (both a total and two known multi-line declarations),
     then asserts no narrow scalar parameter exists and that the C++ guard list
     covers every prototype. */
  const protoSrc = hdr.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\s+/g, " ");
  const protos = [
    ...protoSrc.matchAll(
      /(?:int32_t|uint32_t|void|float)\s+(isaac_room_transition_engine_[a-z0-9_]+)\s*\(([^)]*)\)\s*;/g,
    ),
  ].map((m) => ({
    name: m[1],
    params: m[2]
      .split(",")
      .map((s) => s.trim())
      .filter((s) => s.length > 0 && s !== "void"),
  }));
  assert.ok(protos.length >= 65, `prototype scan saw only ${protos.length}`);
  const seenParams = protos.reduce((n, p) => n + p.params.length, 0);
  // The guard MUST see parameters, and specifically the ones it claims to
  // check: two declarations that span several source lines.
  assert.ok(seenParams >= 160, `the re-census saw only ${seenParams} parameters`);
  const byName = new Map(protos.map((p) => [p.name, p]));
  assert.equal(
    byName.get("isaac_room_transition_engine_408970_plan")?.params.length,
    12,
    "multi-line collapse failed on the v9 970 plan",
  );
  assert.equal(
    byName.get("isaac_room_transition_engine_7abe20_body_plan")?.params.length,
    7,
    "multi-line collapse failed on the v10 body plan",
  );
  const narrow = [];
  for (const p of protos) {
    for (const a of p.params) {
      if (/\*/.test(a)) continue; // pointers to guest memory are fine
      if (/\b(uint8_t|int8_t|uint16_t|int16_t|char|short)\b/.test(a)) {
        narrow.push(`${p.name}(${a})`);
      }
    }
  }
  assert.deepEqual(narrow, [], `narrow scalar parameters survive: ${narrow}`);
  const guarded = new Set(
    [...src.matchAll(/ISAAC_RTE_NO_NARROW_PARAMS\((isaac_[a-z0-9_]+)\)/g)].map(
      (m) => m[1],
    ),
  );
  assert.ok(guarded.size >= protos.length, "guard list is shorter than the export list");
  const unguarded = protos.map((p) => p.name).filter((n) => !guarded.has(n));
  assert.deepEqual(unguarded, [], `exports with no narrow-param guard: ${unguarded}`);

  // v10: the composed body is a COMPOSITION, not a re-implementation — the
  // two anm2-owned callees stay VAs and their residual counts are inputs.
  assert.match(hdr, /isaac_room_transition_engine_7abe20_body_plan/);
  assert.match(hdr, /isaac_room_transition_engine_82ee40_setup_store_plan/);
  assert.match(src, /a5d0_result_byte & 0xffu/);
  assert.match(
    src,
    /ISAAC_RTE_NO_NARROW_PARAMS\(isaac_room_transition_engine_7abe20_nested_830_needed\)/,
  );
});

test("transition engine v3 fix: player loop bound is re-derived every iteration", () => {
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);

  // sar 2 on the byte difference.
  assert.equal(roomTransitionEngine82ee40PlayerCount(0x1000, 0x1000), 0);
  assert.equal(roomTransitionEngine82ee40PlayerCount(0x1000, 0x1010), 4);
  assert.equal(ROOM_TRANSITION_ENGINE_PLAYER_ELEM_STRIDE, 4);
  assert.equal(ROOM_TRANSITION_ENGINE_PLAYER_VEC_OFF, 0x1baa8);
  // Arithmetic shift: a malformed vector (end < begin) yields a negative count.
  assert.equal(roomTransitionEngine82ee40PlayerCount(0x1010, 0x1000), -4);

  // Entry gate is `test/je`, so only zero skips — a negative count enters.
  assert.equal(roomTransitionEngine82ee40PlayerLoopEnter(0), 0);
  assert.equal(roomTransitionEngine82ee40PlayerLoopEnter(1), 1);
  assert.equal(roomTransitionEngine82ee40PlayerLoopEnter(-4), 1);

  // Mid-loop fatal when the re-derived count is 0 at the top of an iteration.
  const empty = roomTransitionEngine82ee40PlayerLoopStep(0, 0x1000, 0x1000);
  assert.equal(empty.count, 0);
  assert.equal(empty.fatalNeeded, 1);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_FATAL, 0x0082f025);
  const nonEmpty = roomTransitionEngine82ee40PlayerLoopStep(0, 0x1000, 0x1008);
  assert.equal(nonEmpty.fatalNeeded, 0);

  // Normal element addressing.
  assert.equal(nonEmpty.elementPtr, 0x1000);
  assert.equal(nonEmpty.clampedToFirst, 0);
  assert.equal(roomTransitionEngine82ee40PlayerLoopStep(1, 0x1000, 0x1008).elementPtr, 0x1004);

  // LATENT ORIGINAL DEFECT, reproduced: index >= count (unsigned) does NOT
  // advance the element pointer, so the PE re-reads element 0. This must stay
  // a clamp — turning it into a loop terminator would change behaviour.
  const clamped = roomTransitionEngine82ee40PlayerLoopStep(2, 0x1000, 0x1008);
  assert.equal(clamped.count, 2);
  assert.equal(clamped.clampedToFirst, 1);
  assert.equal(clamped.elementPtr, 0x1000);
  assert.equal(clamped.indexAfter, 3);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_CLAMP, 0x0082f040);
  // `jae` is unsigned, so a negative index also clamps rather than going back.
  assert.equal(roomTransitionEngine82ee40PlayerLoopStep(-1, 0x1000, 0x1008).clampedToFirst, 1);

  // The continue test uses a bound re-derived AFTER the body's host calls.
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_BOUND, 0x0082f0c3);
  // Same vector: 1 < 2 keeps going.
  assert.equal(roomTransitionEngine82ee40PlayerLoopContinue(1, 0x1000, 0x1008), 1);
  assert.equal(roomTransitionEngine82ee40PlayerLoopContinue(2, 0x1000, 0x1008), 0);
  // Vector GREW during the body -> the loop keeps going past the old bound.
  assert.equal(roomTransitionEngine82ee40PlayerLoopContinue(2, 0x1000, 0x1010), 1);
  // Vector SHRANK during the body -> the loop stops early.
  assert.equal(roomTransitionEngine82ee40PlayerLoopContinue(1, 0x1000, 0x1004), 0);
  // `jb` is unsigned, so a negative re-derived count (end < begin) compares as
  // a huge bound and the PE KEEPS LOOPING. Reproduced, not corrected.
  assert.equal(roomTransitionEngine82ee40PlayerCount(0x1010, 0x1000), -4);
  assert.equal(roomTransitionEngine82ee40PlayerLoopContinue(0, 0x1010, 0x1000), 1);

  // Entry skip gate.
  assert.equal(roomTransitionEngine82ee40PlayerEntryEligible(0), 1);
  assert.equal(roomTransitionEngine82ee40PlayerEntryEligible(1), 0);

  // A whole drive: a vector that grows by one element after the first body
  // visits more entries than a single folded count ever would.
  let index = 0;
  let begin = 0x2000;
  let end = 0x2008; // 2 entries
  let visited = 0;
  assert.equal(
    roomTransitionEngine82ee40PlayerLoopEnter(
      roomTransitionEngine82ee40PlayerCount(begin, end)), 1);
  for (let guard = 0; guard < 16; guard += 1) {
    const step = roomTransitionEngine82ee40PlayerLoopStep(index, begin, end);
    visited += 1;
    if (visited === 1) end = 0x2010; // host call grew the vector to 4
    if (roomTransitionEngine82ee40PlayerLoopContinue(step.indexAfter, begin, end) === 0) break;
    index = step.indexAfter;
  }
  assert.equal(visited, 4, "the re-derived bound must pick up the growth");
});

test("transition engine v3 player loop C++/Wasm lockstep (ABI v11)", () => {
  const {
    abi, memory, playerCount, playerLoopEnter, playerLoopStep,
    playerLoopContinue, playerEntryEligible,
  } = loadExports();
  assert.equal(abi(), 30);
  const view = new DataView(memory.buffer);
  const ptr = MEM + 0x5000;

  let lcg = 0x0c0ffee1;
  const rnd = () => {
    lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0;
    return lcg >>> 0;
  };

  const vectors = [
    [0x1000, 0x1000], [0x1000, 0x1004], [0x1000, 0x1008], [0x1000, 0x1010],
    [0x1010, 0x1000], [0, 0], [0, 0xfffffffc], [0xfffffff0, 0x10],
  ];
  let countCases = 0;
  for (const [b, e] of vectors) {
    assert.equal(playerCount(b, e) | 0, roomTransitionEngine82ee40PlayerCount(b, e), `count ${b}/${e}`);
    countCases += 1;
  }
  for (const c of [-8, -1, 0, 1, 2, 100, 0x7fffffff, -2147483648]) {
    assert.equal(playerLoopEnter(c) | 0, roomTransitionEngine82ee40PlayerLoopEnter(c), `enter ${c}`);
    assert.equal(playerEntryEligible(c) | 0, roomTransitionEngine82ee40PlayerEntryEligible(c));
  }

  const stepKeys = ["count", "fatalNeeded", "index", "clampedToFirst", "elementPtr", "indexAfter"];
  let stepCases = 0;
  for (const [b, e] of vectors) {
    for (const i of [-2, -1, 0, 1, 2, 3, 7, 0x7fffffff]) {
      playerLoopStep(i, b, e, ptr);
      const js = roomTransitionEngine82ee40PlayerLoopStep(i, b, e);
      const tag = `${i}@${b}/${e}`;
      stepKeys.forEach((key, idx) => {
        const got = idx === 4 ? readI32(view, ptr + idx * 4) >>> 0 : readI32(view, ptr + idx * 4) | 0;
        assert.equal(got, js[key], `step ${key} ${tag}`);
      });
      assert.equal(
        playerLoopContinue(i, b, e) | 0,
        roomTransitionEngine82ee40PlayerLoopContinue(i, b, e),
        `continue ${tag}`,
      );
      stepCases += 1;
    }
  }
  assert.equal(stepCases, vectors.length * 8);

  // Draw small ranges from the LCG's HIGH bits: the low bits of this LCG have
  // period 2^k, so `rnd() % n` cycles a tiny subset and overstates coverage.
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;
  let randCases = 0;
  const seenDelta = new Set();
  const seenIdx = new Set();
  for (let n = 0; n < 384; n += 1) {
    const b = (rnd() & 0xfffffff0) >>> 0;
    const delta = hi(9) - 2;
    const e = (b + delta * 4) >>> 0;
    const i = (hi(11) - 3) | 0;
    seenDelta.add(delta);
    seenIdx.add(i);
    playerLoopStep(i, b, e, ptr);
    const js = roomTransitionEngine82ee40PlayerLoopStep(i, b, e);
    stepKeys.forEach((key, idx) => {
      const got = idx === 4 ? readI32(view, ptr + idx * 4) >>> 0 : readI32(view, ptr + idx * 4) | 0;
      assert.equal(got, js[key], `rand step ${key} ${i}@${b}/${e}`);
    });
    assert.equal(playerLoopContinue(i, b, e) | 0,
                 roomTransitionEngine82ee40PlayerLoopContinue(i, b, e),
                 `rand continue ${i}@${b}/${e}`);
    assert.equal(playerCount(b, e) | 0, roomTransitionEngine82ee40PlayerCount(b, e));
    randCases += 1;
  }
  assert.equal(randCases, 384);
  assert.equal(countCases, vectors.length);
  // The corpus must actually reach every seeded value (guards against a
  // regression to low-bits draws that silently narrow coverage).
  assert.equal(seenDelta.size, 9, "corpus must reach all 9 entry-count deltas");
  assert.equal(seenIdx.size, 11, "corpus must reach all 11 start indices");
});

test("transition engine v4: in-loop host-call selection (JS oracle, ABI v11)", () => {
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  assert.equal(ROOM_TRANSITION_ENGINE_PLAYER_173_OFF, 0x173);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_173_GATE, 0x0082f05a);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_ANIM_ARG, 0x0082f063);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_14_GATE, 0x0082f077);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_7ABCC0_CALL, 0x0082f070);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_7ABE20_CALL, 0x0082f084);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_GAME_REREAD, 0x0082f089);

  // 7abcc0 gate: pred && entry+0x173 == 0 (BYTE test on entry+0x173).
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(0, 0), 0);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0), 1);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 1), 0);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0xff), 0);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, -1), 0);
  // Byte gate: wide values above 0xff MUST behave like their low byte.
  // 0x100 low byte 0 -> gate passes; 0x1ff low byte 0xff -> gate fails.
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0x100), 1);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0x1ff), 0);
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0xffffffff), 0);
  // Low byte of 0x80000000 is 0 -> the PE byte test passes.
  assert.equal(roomTransitionEngine82ee407Abcc0Needed(1, 0x80000000), 1);

  // 7abcc0 arg: (anim != 0xb) ? 1 : 0 — full-word compare, setne+movzx.
  assert.equal(roomTransitionEngine82ee407Abcc0Arg(0xb), 0);
  assert.equal(roomTransitionEngine82ee407Abcc0Arg(0xb + 0x100), 1);
  assert.equal(roomTransitionEngine82ee407Abcc0Arg(0), 1);
  assert.equal(roomTransitionEngine82ee407Abcc0Arg(0x10b), 1);
  assert.equal(roomTransitionEngine82ee407Abcc0Arg(-1), 1);

  // 7abe20 gate: field_1c == 0x14 — full-word compare.
  assert.equal(roomTransitionEngine82ee407Abe20Needed(0x14), 1);
  assert.equal(roomTransitionEngine82ee407Abe20Needed(0x114), 0);
  assert.equal(roomTransitionEngine82ee407Abe20Needed(0), 0);
  assert.equal(roomTransitionEngine82ee407Abe20Needed(3), 0);
  assert.equal(roomTransitionEngine82ee407Abe20Needed(-1), 0);

  // Fused plan: all eight pred x entry_173 x field_1c combinations.
  // pred=1, 173=0: 7abcc0 only (arg from anim), Game re-read.
  let plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 0, field1c: 3, anim: 0xb,
  });
  assert.deepEqual(plan, { call7abcc0: 1, arg7abcc0: 0, call7abe20: 0, gameReread: 1 });
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 0, field1c: 3, anim: 0,
  });
  assert.deepEqual(plan, { call7abcc0: 1, arg7abcc0: 1, call7abe20: 0, gameReread: 1 });
  // pred=1, 173 != 0: NO 7abcc0, but 7abe20 still possible on field_1c==0x14.
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 1, field1c: 0x14, anim: 0,
  });
  assert.deepEqual(plan, { call7abcc0: 0, arg7abcc0: 1, call7abe20: 1, gameReread: 1 });
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 1, field1c: 3, anim: 0,
  });
  assert.deepEqual(plan, { call7abcc0: 0, arg7abcc0: 1, call7abe20: 0, gameReread: 0 });
  // pred=0: never 7abcc0; 7abe20 iff field_1c==0x14.
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 0, entry173Byte: 0, field1c: 0x14, anim: 0xb,
  });
  assert.deepEqual(plan, { call7abcc0: 0, arg7abcc0: 0, call7abe20: 1, gameReread: 1 });
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 0, entry173Byte: 0xff, field1c: 0, anim: 0xb,
  });
  assert.deepEqual(plan, { call7abcc0: 0, arg7abcc0: 0, call7abe20: 0, gameReread: 0 });
  // Wide byte input on the fused plan too.
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 0x100, field1c: 0, anim: 0,
  });
  assert.deepEqual(plan, { call7abcc0: 1, arg7abcc0: 1, call7abe20: 0, gameReread: 1 });
  plan = roomTransitionEngine82ee40PlayerCallPlan({
    predicate: 1, entry173Byte: 0x1ff, field1c: 0, anim: 0,
  });
  assert.deepEqual(plan, { call7abcc0: 0, arg7abcc0: 1, call7abe20: 0, gameReread: 0 });
});

test("transition engine v4: player call plan C++/Wasm lockstep (ABI v11)", () => {
  const {
    abi, memory, call7abcc0Needed, call7abcc0Arg, call7abe20Needed, callPlan,
  } = loadExports();
  assert.equal(abi(), 30);
  const view = new DataView(memory.buffer);
  const ptr = MEM + 0x6000;

  let lcg = 0x0c0ffee1;
  const rnd = () => {
    lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0;
    return lcg >>> 0;
  };
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;

  // Fixed truth table (64 cases: pred 0/1 x byte {0,1,0xff,0x100,0x1ff,-1}
  // x field_1c {0,3,0x14,0x114} x anim {0,0xb,0x10b}).
  const bytes = [0, 1, 0xff, 0x100, 0x1ff, 0xffffffff, 0x80000000];
  const fields = [0, 3, 0x14, 0x114, -1, 0x7fffffff];
  const anims = [0, 0xb, 0x10b, -1, 0x7fffffff, 0xffffffff | 0];
  let fixedCases = 0;
  for (const pred of [0, 1]) {
    for (const b of bytes) {
      assert.equal(
        call7abcc0Needed(pred, b) | 0,
        roomTransitionEngine82ee407Abcc0Needed(pred, b),
        `7abcc0Needed pred=${pred} byte=${b >>> 0}`,
      );
      for (const f of fields) {
        assert.equal(
          call7abe20Needed(f) | 0,
          roomTransitionEngine82ee407Abe20Needed(f),
          `7abe20Needed field=${f}`,
        );
        for (const a of anims) {
          assert.equal(
            call7abcc0Arg(a) | 0,
            roomTransitionEngine82ee407Abcc0Arg(a),
            `7abcc0Arg anim=${a}`,
          );
          callPlan(pred, b, f, a, ptr);
          const js = roomTransitionEngine82ee40PlayerCallPlan({
            predicate: pred, entry173Byte: b, field1c: f, anim: a,
          });
          assert.equal(readI32(view, ptr + 0), js.call7abcc0, `call7abcc0 ${pred}/${b >>> 0}/${f}/${a}`);
          assert.equal(readI32(view, ptr + 4), js.arg7abcc0, `arg7abcc0 ${pred}/${b >>> 0}/${f}/${a}`);
          assert.equal(readI32(view, ptr + 8), js.call7abe20, `call7abe20 ${pred}/${b >>> 0}/${f}/${a}`);
          assert.equal(readI32(view, ptr + 12), js.gameReread, `gameReread ${pred}/${b >>> 0}/${f}/${a}`);
          fixedCases += 1;
        }
      }
    }
  }
  assert.equal(fixedCases, 2 * bytes.length * fields.length * anims.length);

  // Randomized differential (384 draws, wide byte inputs included).
  let randCases = 0;
  const seenPred = new Set();
  const seenField = new Set();
  const seenAnim = new Set();
  for (let n = 0; n < 384; n += 1) {
    const pred = hi(2);
    const b = hi(8) === 0 ? (0x100 << hi(8)) >>> 0 : hi(256);
    const f = [0, 3, 0xb, 0xc, 0xd, 0x14, 0x15, 0x114, -1][hi(9)];
    const a = [0, 0xb, 0x10b, 20, -1, 0x7fffffff][hi(6)];
    seenPred.add(pred);
    seenField.add(f);
    seenAnim.add(a);
    callPlan(pred, b, f, a, ptr);
    const js = roomTransitionEngine82ee40PlayerCallPlan({
      predicate: pred, entry173Byte: b, field1c: f, anim: a,
    });
    assert.equal(readI32(view, ptr + 0), js.call7abcc0, `rand call7abcc0 ${pred}/${b >>> 0}/${f}/${a}`);
    assert.equal(readI32(view, ptr + 4), js.arg7abcc0, `rand arg7abcc0 ${pred}/${b >>> 0}/${f}/${a}`);
    assert.equal(readI32(view, ptr + 8), js.call7abe20, `rand call7abe20 ${pred}/${b >>> 0}/${f}/${a}`);
    assert.equal(readI32(view, ptr + 12), js.gameReread, `rand gameReread ${pred}/${b >>> 0}/${f}/${a}`);
    randCases += 1;
  }
  assert.equal(randCases, 384);
  assert.equal(seenPred.size, 2, "corpus must reach both predicate values");
  assert.equal(seenField.size, 9, "corpus must reach all 9 field_1c values");
  assert.equal(seenAnim.size, 6, "corpus must reach all 6 anim values");
});

test("transition engine v5: per-entry body FUN_007abe20 pure core (JS oracle, ABI v11)", () => {
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  // Entry object offsets and body call sites recovered from the raw PE
  // (section table .text raw 0x400 + (VA - 0x401000), VA 0x007abe20).
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_8C_OFF, 0x8c);
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_14C_OFF, 0x14c);
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_139A_OFF, 0x139a);
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_1398_OFF, 0x1398);
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_41C_OFF, 0x41c); // ANM2::Reset rx
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_98_OFF, 0x98);   // 0x408830 rx
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_48_OFF, 0x48);   // 0x40a5d0 rx
  assert.equal(ROOM_TRANSITION_ENGINE_ENTRY_78_OFF, 0x78);   // Rewind rx
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_407F10, 0x00407f10);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_408830, 0x00408830);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_40A5D0, 0x0040a5d0);
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_40A1B0, 0x0040a1b0);
  assert.equal(ROOM_TRANSITION_ENGINE_STORE_VA_139A_HEAD, 0x007abe2e);
  assert.equal(ROOM_TRANSITION_ENGINE_STORE_VA_14C, 0x007abe42);
  assert.equal(ROOM_TRANSITION_ENGINE_STORE_VA_8C, 0x007abe6a);
  assert.equal(ROOM_TRANSITION_ENGINE_STORE_VA_139A_TAIL, 0x007abe71);
  assert.equal(ROOM_TRANSITION_ENGINE_STORE_VA_1398, 0x007abe78);
  // param_2 .rdata consts at the three callers.
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_82F07D, 0x00b6ce1c);
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGNONZERO, 0x00b1dff0);
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGZERO, 0x00b1e010);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABE20_STORE_COUNT, 5);

  // `test al,al` byte gate on the 0x40a5d0 result.
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0), 0);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(1), 1);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0xff), 1);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0x7f), 1);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0x80), 1); // low byte 0x80 != 0
  // Wide values: the PE masks to AL, so the gate must follow the low byte.
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0x100), 0);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0x1ff), 1);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0xffffffff), 1);
  assert.equal(roomTransitionEngine7abe20RewindNeeded(0x80000000), 0);

  // Decision mirrors the same byte test.
  let d = roomTransitionEngine7abe20RewindDecision(0);
  assert.deepEqual(d, { rewindNeeded: 0, store8c: 0 });
  d = roomTransitionEngine7abe20RewindDecision(0x100);
  assert.deepEqual(d, { rewindNeeded: 0, store8c: 0 });
  d = roomTransitionEngine7abe20RewindDecision(1);
  assert.deepEqual(d, { rewindNeeded: 1, store8c: 1 });
  d = roomTransitionEngine7abe20RewindDecision(0x1ff);
  assert.deepEqual(d, { rewindNeeded: 1, store8c: 1 });

  // Store surface: five STATIC records in PE order, offsets/values/anchors
  // exact on every path. Record 2 (0x8c) is THE conditional store (gated==1);
  // the runtime RewindDecision decides whether it is fired.
  const plan = roomTransitionEngine7abe20StorePlan();
  assert.equal(plan.length, 5);
  assert.deepEqual(plan[0], { offset: 0x139a, value: 0, peVa: 0x007abe2e, width: 1, gated: 0 });
  assert.deepEqual(plan[1], { offset: 0x14c, value: 0x3f800000, peVa: 0x007abe42, width: 4, gated: 0 });
  assert.deepEqual(plan[2], { offset: 0x8c, value: 1, peVa: 0x007abe6a, width: 1, gated: 1 });
  assert.deepEqual(plan[3], { offset: 0x139a, value: 0, peVa: 0x007abe71, width: 1, gated: 0 });
  assert.deepEqual(plan[4], { offset: 0x1398, value: 1, peVa: 0x007abe78, width: 1, gated: 0 });
  // Exactly one gated record (the 0x8c store), no runtime dependence: the
  // plan for a zero-result draw is identical to the plan for a nonzero one.
  assert.deepEqual(roomTransitionEngine7abe20StorePlan(), plan, "plan is static");
  assert.equal(plan.filter((r) => r.gated === 1).length, 1, "exactly one gated store");
});

test("transition engine v5: per-entry body C++/Wasm lockstep (ABI v11)", () => {
  const {
    abi, memory, rewindNeeded, rewindDecision, storePlan,
  } = loadExports();
  assert.equal(abi(), 30);
  const view = new DataView(memory.buffer);
  const DEC = MEM + 0x7000;
  const PLAN = MEM + 0x7100;

  let lcg = 0x0c0ffee1;
  const rnd = () => {
    lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0;
    return lcg >>> 0;
  };
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;

  const readRecord = (base, i) => ({
    offset: readI32(view, base + i * 20 + 0) >>> 0,
    value: readI32(view, base + i * 20 + 4) >>> 0,
    peVa: readI32(view, base + i * 20 + 8) >>> 0,
    width: readI32(view, base + i * 20 + 12) >>> 0,
    gated: readI32(view, base + i * 20 + 16) >>> 0,
  });
  const readPlan = (base) => Array.from({ length: 5 }, (_, i) => readRecord(base, i));
  const sameRecord = (a, b) =>
    a.offset === b.offset && a.value === b.value && a.peVa === b.peVa &&
    a.width === b.width && a.gated === b.gated;
  const samePlan = (a, b) =>
    a.length === b.length && a.every((r, i) => sameRecord(r, b[i]));
  const jsPlan = roomTransitionEngine7abe20StorePlan();

  // The store surface is STATIC: compare the Wasm plan once against the
  // oracle records (offsets, values, anchors, widths, gates).
  storePlan(PLAN);
  assert.ok(samePlan(readPlan(PLAN), jsPlan), "Wasm store plan matches oracle");

  // Fixed corpus (wide byte values included, never pre-masked).
  const fixed = [0, 1, 0xff, 0x7f, 0x80, 0x100, 0x1ff, 0xffffffff, 0x80000000, 0x12345678, -1];
  let fixedCases = 0;
  for (const r of fixed) {
    assert.equal(
      rewindNeeded(r) | 0,
      roomTransitionEngine7abe20RewindNeeded(r),
      `rewindNeeded 0x${(r >>> 0).toString(16)}`,
    );
    rewindDecision(r, DEC);
    const jsDec = roomTransitionEngine7abe20RewindDecision(r);
    assert.equal(readI32(view, DEC + 0), jsDec.rewindNeeded, `dec.rewind ${r >>> 0}`);
    assert.equal(readI32(view, DEC + 4), jsDec.store8c, `dec.store8c ${r >>> 0}`);
    fixedCases += 1;
  }
  assert.equal(fixedCases, fixed.length);

  // Randomized differential (384 draws, from the LCG HIGH bits).
  const results = [0, 1, 0xff, 0x100, 0x1ff, 0xffffffff, 0x80000000, 0x7f, 0x80, 0x12345678];
  let randCases = 0;
  const seen = new Set();
  for (let n = 0; n < 384; n += 1) {
    const r = hi(4) === 0 ? (0x100 << hi(24)) >>> 0 : results[hi(results.length)];
    seen.add(r);
    assert.equal(rewindNeeded(r) | 0, roomTransitionEngine7abe20RewindNeeded(r), `rand rewind ${r >>> 0}`);
    rewindDecision(r, DEC);
    const jsDec = roomTransitionEngine7abe20RewindDecision(r);
    assert.equal(readI32(view, DEC + 0), jsDec.rewindNeeded, `rand dec.rewind ${r >>> 0}`);
    assert.equal(readI32(view, DEC + 4), jsDec.store8c, `rand dec.store8c ${r >>> 0}`);
    randCases += 1;
  }
  assert.equal(randCases, 384);
  assert.ok(seen.has(0) && seen.has(1) && seen.has(0x100) && seen.has(0x1ff) && seen.has(0xffffffff),
    "corpus must reach every gate class");

  // Behavioural application of the typed contracts to a scratch entry:
  // unconditional records always; the single gated record (0x8c) ONLY when
  // the runtime RewindDecision fires. Wasm and oracle must agree on the
  // final entry bytes, including the stale-kept 0x8c on the zero path.
  const applyPlan = (recs, w, fireGated) => {
    for (const rec of recs) {
      if (rec.gated === 1 && fireGated !== 1) continue;
      if (rec.width === 4) w.setUint32(rec.offset, rec.value >>> 0, true);
      else w.setUint8(rec.offset, rec.value & 0xff);
    }
  };
  const wasmPlan = readPlan(PLAN);
  for (const r of [0, 0x100, 0x80000000, 0xffffffff, 1, 0x1ff, 0x7f]) {
    const w1 = new DataView(new ArrayBuffer(0x1400));
    const w2 = new DataView(new ArrayBuffer(0x1400));
    w1.setUint8(0x8c, 0x77); w2.setUint8(0x8c, 0x77);
    w1.setUint32(0x14c, 0xdeadbeef, true); w2.setUint32(0x14c, 0xdeadbeef, true);
    const fire = roomTransitionEngine7abe20RewindNeeded(r);
    applyPlan(wasmPlan, w1, fire);
    applyPlan(jsPlan, w2, fire);
    for (const off of [0x8c, 0x14c, 0x139a, 0x1398]) {
      const a = off === 0x14c ? w1.getUint32(off, true) : w1.getUint8(off);
      const b = off === 0x14c ? w2.getUint32(off, true) : w2.getUint8(off);
      assert.equal(a, b, `apply ${off} r=${r >>> 0}`);
    }
    if (fire === 0) {
      // The gated byte is NOT written when the host result low byte is 0:
      // the PE has no store instruction on the AL==0 path.
      assert.equal(w1.getUint8(0x8c), 0x77, "0x8c must stay stale on low-byte-zero");
    } else {
      assert.equal(w1.getUint8(0x8c), 1, "0x8c must be 1 on the rewind path");
    }
  }
});

test("transition engine v6: FUN_007abcc0 pure shell + SFX pack (JS oracle, ABI v11)", () => {
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  // The three param_2 consts are animation-name strings (PE .rdata verified
  // by the PE-truth test below); v6 names the direction explicitly.
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_82F07D, 0x00b6ce1c); // "DeathTeleport"
  // v7/D3: the address law is unchanged, but the STRING labels v6 attached to
  // these two addresses were inverted. The raw-PE test below is the authority.
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGZERO, 0x00b1e010); // "TeleportDown"
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGNONZERO, 0x00b1dff0); // "TeleportUp"
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_82F07D_STR, "DeathTeleport");
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_ARGZERO_STR, "TeleportDown");
  assert.equal(ROOM_TRANSITION_ENGINE_PARAM2_ARGNONZERO_STR, "TeleportUp");

  // Wrapper call-site anchors.
  assert.equal(ROOM_TRANSITION_ENGINE_HOST_VA_7ABCC0, 0x007abcc0);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_CMOVE_VA, 0x007abcd5);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_7ABE20_CALL_VA, 0x007abcd9);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_SFX_GATE_VA, 0x007abcde);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_ID_STORE_VA, 0x007abceb);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_PREP_CALL_VA, 0x007abcf2);
  assert.equal(ROOM_TRANSITION_ENGINE_7ABCC0_PLAY_CALL_VA, 0x007abd1e);
  assert.equal(ROOM_TRANSITION_ENGINE_82EE40_SFX_GATE_VA, 0x0082f14f);
  assert.equal(ROOM_TRANSITION_ENGINE_82EE40_SFX_ID_VA, 0x0082f16b);
  assert.equal(ROOM_TRANSITION_ENGINE_82EE40_PREP_CALL_VA, 0x0082f16e);
  assert.equal(ROOM_TRANSITION_ENGINE_82EE40_PLAY_CALL_VA, 0x0082f19a);

  // CMOVZ law: low byte == 0 -> TeleportUp (0xb1e010); else TeleportDown.
  assert.equal(roomTransitionEngine7abcc0Param2(0), 0x00b1e010);
  assert.equal(roomTransitionEngine7abcc0Param2(1), 0x00b1dff0);
  assert.equal(roomTransitionEngine7abcc0Param2(0xff), 0x00b1dff0);
  // Wide byte values MUST behave like their low byte (Wasm ABI never narrows).
  assert.equal(roomTransitionEngine7abcc0Param2(0x100), 0x00b1e010);
  assert.equal(roomTransitionEngine7abcc0Param2(0x1ff), 0x00b1dff0);
  assert.equal(roomTransitionEngine7abcc0Param2(0xffffffff), 0x00b1dff0);
  assert.equal(roomTransitionEngine7abcc0Param2(0x80000000), 0x00b1e010);

  // SFX gate: `test bl,bl; je` — runs iff low byte != 0.
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0), 0);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(1), 1);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0xff), 1);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0x100), 0);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0x1ff), 1);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0xffffffff), 1);
  assert.equal(roomTransitionEngine7abcc0SfxNeeded(0x80000000), 0);

  // Fused plan: param2 + gate + pre-prep id const 0xd7.
  let plan = roomTransitionEngine7abcc0Plan(0);
  assert.deepEqual(plan, { param2: 0x00b1e010, sfxNeeded: 0, sfxId: 0xd7 });
  plan = roomTransitionEngine7abcc0Plan(1);
  assert.deepEqual(plan, { param2: 0x00b1dff0, sfxNeeded: 1, sfxId: 0xd7 });
  plan = roomTransitionEngine7abcc0Plan(0x100);
  assert.deepEqual(plan, { param2: 0x00b1e010, sfxNeeded: 0, sfxId: 0xd7 });
  plan = roomTransitionEngine7abcc0Plan(0x1ff);
  assert.deepEqual(plan, { param2: 0x00b1dff0, sfxNeeded: 1, sfxId: 0xd7 });

  // Shared SFX residual pack (engine H3 + 7abcc0 block): constants only, so
  // the plan is STATIC — two calls must agree on every field.
  const pack = roomTransitionEngineSfxPlayPack();
  assert.deepEqual(pack, {
    volumeBits: 0x3f800000, frameDelay: 2, loop: 0, pitchBits: 0x3f800000,
    pan: 0, receiverOff: 0x2a324, prepVa: 0x00956780, playVa: 0x0092dc30,
  });
  assert.deepEqual(roomTransitionEngineSfxPlayPack(), pack, "pack is static");
  assert.equal(ROOM_TRANSITION_ENGINE_SFX_GLOBAL_VA, 0x00c7169c);
  assert.equal(ROOM_TRANSITION_ENGINE_SFX_ID_7ABCC0, 0xd7);
  assert.equal(ROOM_TRANSITION_ENGINE_SFX_ID_DIM1, 0x260);
  assert.equal(ROOM_TRANSITION_ENGINE_SFX_ID_DIMOTHER, 0x261);
  // Cross-check with the engine's own id select (v1 helper): dim==1 -> 0x260.
  assert.equal(roomTransitionEngine82ee40Anim12SfxId(1), ROOM_TRANSITION_ENGINE_SFX_ID_DIM1);
  assert.equal(roomTransitionEngine82ee40Anim12SfxId(0), ROOM_TRANSITION_ENGINE_SFX_ID_DIMOTHER);
});

test("transition engine v6: PE-truth pins for 7abcc0 (cmove bytes + .rdata strings)", () => {
  const asCString = (b) => {
    let s = "";
    for (const c of b) {
      if (c === 0) break;
      s += String.fromCharCode(c);
    }
    return s;
  };

  // The three param_2 consts are animation-name strings, not ints.
  assert.equal(asCString(peRaw(0x00b6ce1c, 16)), "DeathTeleport");
  assert.equal(asCString(peRaw(0x00b1e010, 16)), "TeleportDown");
  assert.equal(asCString(peRaw(0x00b1dff0, 16)), "TeleportUp");

  // v7/D3: the EXPORTED labels must be the strings the PE actually holds at
  // the two cmove targets. This is the assertion v6 lacked: it read the right
  // bytes here and exported the opposite names, and nothing compared them.
  assert.equal(
    asCString(peRaw(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGZERO, 16)),
    ROOM_TRANSITION_ENGINE_PARAM2_ARGZERO_STR,
    "arg-byte-zero target must hold the exported ARGZERO string",
  );
  assert.equal(
    asCString(peRaw(ROOM_TRANSITION_ENGINE_PARAM2_7ABCC0_ARGNONZERO, 16)),
    ROOM_TRANSITION_ENGINE_PARAM2_ARGNONZERO_STR,
    "arg-byte-nonzero target must hold the exported ARGNONZERO string",
  );
  assert.equal(
    asCString(peRaw(ROOM_TRANSITION_ENGINE_PARAM2_82F07D, 16)),
    ROOM_TRANSITION_ENGINE_PARAM2_82F07D_STR,
  );
  // ...and the exported addresses must be different objects.
  assert.notEqual(
    ROOM_TRANSITION_ENGINE_PARAM2_ARGZERO_STR,
    ROOM_TRANSITION_ENGINE_PARAM2_ARGNONZERO_STR,
  );

  // CMOVZ direction pinned by the exact instruction bytes of the select:
  //   mov edx, 0xb1e010 (BA 10 E0 B1 00) / test bl,bl (84 DB)
  //   mov eax, 0xb1dff0 (B8 F0 DF B1 00) / cmove eax,edx (0F 44 C2)
  // ZF from `test bl,bl` -> bl == 0 moves 0xb1e010 ("TeleportUp") into eax.
  const cmove = Array.from(peRaw(0x007abcc8, 16));
  assert.deepEqual(cmove, [0xba, 0x10, 0xe0, 0xb1, 0x00, 0x84, 0xdb, 0xb8,
                           0xf0, 0xdf, 0xb1, 0x00, 0x56, 0x0f, 0x44, 0xc2],
                   "cmove instruction bytes must pin the param2 select law");
});

test("transition engine v6: 7abcc0 shell + SFX pack C++/Wasm lockstep (ABI v11)", () => {
  const {
    abi, memory, param2, sfxNeeded, wrapperPlan, sfxPack,
  } = loadExports();
  assert.equal(abi(), 30);
  const view = new DataView(memory.buffer);
  const PLAN = MEM + 0x8000;
  const PACK = MEM + 0x8100;

  let lcg = 0x0c0ffee1;
  const rnd = () => {
    lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0;
    return lcg >>> 0;
  };
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;

  // Fixed corpus: every byte-gate class, wide values never pre-masked.
  const fixed = [0, 1, 0xff, 0x100, 0x1ff, 0xffffffff, 0x80000000, 0x7f, 0x80, 0x12345678];
  let fixedCases = 0;
  for (const a of fixed) {
    assert.equal(param2(a) >>> 0, roomTransitionEngine7abcc0Param2(a) >>> 0, `param2 0x${(a >>> 0).toString(16)}`);
    assert.equal(sfxNeeded(a) | 0, roomTransitionEngine7abcc0SfxNeeded(a), `sfxNeeded 0x${(a >>> 0).toString(16)}`);
    wrapperPlan(a, PLAN);
    const jsPlan = roomTransitionEngine7abcc0Plan(a);
    assert.equal(readI32(view, PLAN + 0) >>> 0, jsPlan.param2 >>> 0, `plan.param2 ${a >>> 0}`);
    assert.equal(readI32(view, PLAN + 4) | 0, jsPlan.sfxNeeded, `plan.sfxNeeded ${a >>> 0}`);
    assert.equal(readI32(view, PLAN + 8) >>> 0, jsPlan.sfxId, `plan.sfxId ${a >>> 0}`);
    fixedCases += 1;
  }
  assert.equal(fixedCases, fixed.length);

  // Pack is static: compare every field once (and re-check stability).
  sfxPack(PACK);
  const jsPack = roomTransitionEngineSfxPlayPack();
  const packKeys = [
    ["volumeBits", 0], ["frameDelay", 4], ["loop", 8], ["pitchBits", 12],
    ["pan", 16], ["receiverOff", 20], ["prepVa", 24], ["playVa", 28],
  ];
  for (const [key, off] of packKeys) {
    assert.equal(readI32(view, PACK + off) >>> 0, jsPack[key] >>> 0, `pack.${key}`);
  }
  sfxPack(PACK + 32);
  for (const [, off] of packKeys) {
    assert.equal(readI32(view, PACK + 32 + off), readI32(view, PACK + off), "pack stability");
  }

  // Randomized differential (384 draws from the LCG HIGH bits; the corpus must
  // hit every byte-gate class, including wide values).
  let randCases = 0;
  const seen = new Set();
  for (let n = 0; n < 384; n += 1) {
    // Deterministic byte-gate classes: 0, 0xff, wide-with-low-0 (0x100<<k),
    // wide-with-low-ff ((0x100<<k)|0xff), and uniform random bytes — with
    // wide values NEVER pre-masked, exactly as the corpus contract requires.
    const roll = hi(5);
    let a;
    if (roll === 0) a = 0;
    else if (roll === 1) a = 0xff;
    else if (roll === 2) a = (0x100 << hi(24)) >>> 0;
    else if (roll === 3) a = ((0x100 << hi(24)) | 0xff) >>> 0;
    else a = hi(256);
    seen.add((a & 0xff) === 0 ? "low0" : (a & 0xff) === 0xff ? "lowff" : "other");
    assert.equal(param2(a) >>> 0, roomTransitionEngine7abcc0Param2(a) >>> 0, `rand param2 ${a >>> 0}`);
    assert.equal(sfxNeeded(a) | 0, roomTransitionEngine7abcc0SfxNeeded(a), `rand sfxNeeded ${a >>> 0}`);
    wrapperPlan(a, PLAN);
    const jsPlan = roomTransitionEngine7abcc0Plan(a);
    assert.equal(readI32(view, PLAN + 0) >>> 0, jsPlan.param2 >>> 0, `rand plan.param2 ${a >>> 0}`);
    assert.equal(readI32(view, PLAN + 4) | 0, jsPlan.sfxNeeded, `rand plan.sfxNeeded ${a >>> 0}`);
    assert.equal(readI32(view, PLAN + 8) >>> 0, jsPlan.sfxId, `rand plan.sfxId ${a >>> 0}`);
    randCases += 1;
  }
  assert.equal(randCases, 384);
  assert.ok(seen.has("low0") && seen.has("lowff") && seen.has("other"),
    "corpus must reach every byte-gate class");

  // Behavioural application: a mock host runner executes the wrapper sequence
  // with the Wasm plan vs the oracle plan; the resulting entry/Play surfaces
  // must be identical, including the id being rewritten by the host prep.
  const runWrapper = (planData, packData) => {
    const out = { param2: planData.param2, sfxRan: 0, playId: -1, vol: -1, delay: -1,
                  loop: -1, pitch: -1, pan: -1, receiver: -1 };
    // HOST 0x007abe20(entry, param2) — the body call is host; record param2.
    out.param2 = planData.param2 >>> 0;
    if (planData.sfxNeeded === 1) {
      out.sfxRan = 1;
      let id = planData.sfxId >>> 0;         // 0xd7 const
      id = (id + 0x25) & 0xffffffff;         // HOST 0x00956780 rewrote *id
      out.playId = id;
      out.vol = packData.volumeBits >>> 0;
      out.delay = packData.frameDelay | 0;
      out.loop = packData.loop | 0;
      out.pitch = packData.pitchBits >>> 0;
      out.pan = packData.pan | 0;
      out.receiver = (packData.receiverOff >>> 0); // + [0xc7169c] host deref
    }
    return out;
  };
  for (const a of [0, 1, 0x100, 0x1ff, 0xffffffff]) {
    const wasmPack = {};
    for (const [key, off] of packKeys) wasmPack[key] = readI32(view, PACK + off) >>> 0;
    // Rebuild the plan for THIS draw through the Wasm export.
    wrapperPlan(a, PLAN);
    const wp = {
      param2: readI32(view, PLAN + 0) >>> 0,
      sfxNeeded: readI32(view, PLAN + 4) | 0,
      sfxId: readI32(view, PLAN + 8) >>> 0,
    };
    assert.deepEqual(
      runWrapper(wp, wasmPack),
      runWrapper(roomTransitionEngine7abcc0Plan(a), roomTransitionEngineSfxPlayPack()),
      `runner surface for arg 0x${(a >>> 0).toString(16)}`,
    );
  }
});

