  for (const [name, value] of Object.entries(PINNED)) {
    assert.ok(found.has(name), `pinned header constant ${name} vanished`);
    assert.equal(found.get(name), value, `header constant ${name}`);
  }

  // 2. Every ISAAC_..._HOST_VA_* / _STORE_VA_* / _*_VA constant must be a
  //    real VA inside a raw-backed section, and every VA that names an
  //    instruction site inside this build must be in .text.
  for (const [name, value] of found) {
    if (!/_VA(_|$)|_VA[0-9A-Z_]*$/.test(name)) continue;
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_DATA_RAW_END_VA") continue;
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_C7B640_VA") continue;
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_C7B644_VA") continue;
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_SFX_GLOBAL_VA") continue; // .data
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_STATS_HEAD_VA") continue; // BSS
    if (name === "ISAAC_ROOM_TRANSITION_ENGINE_STATS_FIXED_VA") continue; // BSS
    if (value < 0x00401000) continue; // field offsets that happen to match
    const sect = peSectionOf(value);
    assert.ok(sect !== null, `${name} = 0x${value.toString(16)} is not in any section`);
    assert.equal(peFileBacked(value), true, `${name} must be file-backed`);
    if (/HOST_VA|STORE_VA|_CALL_VA|_GATE_VA|CMOVE_VA|ID_STORE_VA|_40A5D0_VA_/.test(name)) {
      assert.ok(
        sect.name === ".text",
        `${name} = 0x${value.toString(16)} names an instruction site but is in ${sect.name}`,
      );
    }
  }

