  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42A250_VA_RET = 0x0042a257u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42A250_BODY_BYTES = 8u/);
