  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42A260_VA = 0x0042a260u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42A260_BODY_BYTES = 7u/);
