  for (const name of [
    "eq3Check42a250", "get42a260", "chain42a270", "fallback42a270",
  ]) {
    assert.equal(typeof api[name], "function", `export ${name}`);
  }
  /* Raw disasm needles (disasm-0042a250-0042a270.txt). */
