  /* Model constants agree (V22 mirror). */
  assert.equal(ROOM_TRANSITION_ENGINE_42A290_VA, 0x0042a290);
  assert.equal(ROOM_TRANSITION_ENGINE_42A290_BOUND, 0x1bf);
  assert.equal(ROOM_TRANSITION_ENGINE_42A290_ARRAY_BASE_OFF, 0x76c);
  assert.equal(ROOM_TRANSITION_ENGINE_42A2C0_FIELD_4_OFF, 0x4);
  assert.equal(ROOM_TRANSITION_ENGINE_42A310_FIELD_1340_OFF, 0x1340);
  assert.equal(ROOM_TRANSITION_ENGINE_42A320_BYTE_MASK, 0xff);
  assert.equal(ROOM_TRANSITION_ENGINE_42A330_FIELD_1A740_OFF, 0x1a740);
  assert.equal(ROOM_TRANSITION_ENGINE_42A340_FIELD_1BB84_OFF, 0x1bb84);
  /* All 6 exports load in the wasm module. */
