test("v22 POOL: scalar laws (unsigned bound / null-check / byte mask / lea adds)", () => {
  const api = loadExports();
  /* 42a290 accepts: UNSIGNED <= 0x1bf — wide drives never match the
     SIGNED misread (0x80000000 would be negative-signed). */
  for (const v of [0, 1, 0x1be, 0x1bf, 0x1c0, 0xffff, 0x7fffffff,
                   0x80000000, 0xffffffff]) {
    assert.equal(api.accepts42a290(v >>> 0) | 0,
                 roomTransitionEngine42a290Accepts(v), `accepts ${v}`);
  }
  /* 42a2c0 non-null. */
  for (const v of [0, 1, 0xffffffff]) {
    assert.equal(api.nonNull42a2c0(v >>> 0) | 0,
                 roomTransitionEngine42a2c0NonNull(v), `nonnull ${v}`);
  }
  /* 42a320 BYTE-width load: only the low byte is observable. */
  const view = new DataView(api.memory.buffer);
  const R = MEM + 0xf8000;
  view.setUint32(R + 0x20a9, 0x1234abcd, true); // nonzero high bytes
  assert.equal(api.byteGet42a320(R) >>> 0, 0xcd,
    "byte getter masks to the low byte");
  const mB = new Uint8Array(0x4000);
  for (let i = 0; i < 4; i += 1) mB[0x20a9 + i] = (0x1234abcd >>> (8 * i)) & 0xff;
  assert.equal(roomTransitionEngine42a320ByteGetter({ mem: mB, thisOff: 0 }) >>> 0,
               0xcd, "byte getter model");
  /* 42a330/42a340 field-pointer getters: u32-wrapping adds. */
  for (const t of [0, 1, 0x7fffffff, 0xffffffff]) {
    assert.equal(api.get42a330(t >>> 0) >>> 0,
                 roomTransitionEngine42a330FieldGetter(t), `a330 ${t}`);
    assert.equal(api.get42a340(t >>> 0) >>> 0,
                 roomTransitionEngine42a340FieldGetter(t), `a340 ${t}`);
  }
});

test("v22 POOL: lockstep memory laws (value getter / byte getter over wasm arena)", () => {
  const api = loadExports();
  const view = new DataView(api.memory.buffer);
  const R = MEM + 0xfc000;
  let lcg = 0x42a310;
  const rnd = () => { lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0; return lcg >>> 0; };
  for (let n = 0; n < 256; n += 1) {
    const thisOff = rnd() % 0x200;
    const v = rnd();
    view.setUint32(R + thisOff + 0x1340, v, true);
    view.setUint32(R + thisOff + 0x20a9, v ^ 0x5a5a5a5a, true);
    const mSnap = new Uint8Array(0x2000);
    for (let bI = 0; bI < 0x2000; bI += 1) mSnap[bI] = view.getUint8(R + bI);
    const wD = api.get42a310(R, thisOff) >>> 0;
    const jD = roomTransitionEngine42a310ValueGetter({ mem: mSnap, thisOff }) >>> 0;
    assert.equal(wD, jD, `a310 trial ${n} lockstep`);
    assert.equal(wD, v >>> 0, `a310 exact ${n}`);
    const wB = api.byteGet42a320(R, thisOff) >>> 0;
    assert.equal(wB, (v ^ 0x5a5a5a5a) & 0xff, `a320 trial ${n}`);
  }
});

test("v22 POOL: deterministic randomized differential corpus (500 draws)", () => {
  const api = loadExports();
  let seed = 0x0042a290 >>> 0;
  const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  let cases = 0;
  for (let i = 0; i < 500; i++) {
    const idx = rnd() >>> 0;
    const f4 = rnd() >>> 0;
    assert.equal(api.accepts42a290(idx) | 0,
                 roomTransitionEngine42a290Accepts(idx), `trial ${i} accepts-model`);
    assert.equal(api.nonNull42a2c0(f4) | 0,
                 roomTransitionEngine42a2c0NonNull(f4), `trial ${i} nonnull-model`);
    const t = rnd() >>> 0;
    const wE = api.get42a330(t) >>> 0;
    const wF = api.get42a340(t) >>> 0;
    assert.equal(wE, roomTransitionEngine42a330FieldGetter(t), `trial ${i} a330-model`);
    assert.equal(wF, roomTransitionEngine42a340FieldGetter(t), `trial ${i} a340-model`);
    /* coherence: the two getters differ by exactly the offset delta. */
    assert.equal((wF - wE) | 0, ((0x1bb84 - 0x1a740) | 0), `trial ${i} delta`);
    cases += 5;
  }
  assert.ok(cases >= 2500, `expected >= 2500 cases, got ${cases}`);
});

/* =====================================================================
 * v23 — 0x0042b020 multi-table switch classifier (797 B, FULLY PURE).
 * One law: contains(arg) over BOTH pinned byte tables. Boundaries:
 * 0xe8 (je TRUE), 0xcc (low bound), 0x1eb (high bound); jg SIGNED.
 * ===================================================================== */

test("v23 42b020: build + ABI pin + census + table pins match the PE", () => {
  const api = loadExports();
  assert.equal(api.abi(), 30); // pre-flip
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  const h = readFileSync(header, "utf8");
  assert.match(h, /v23 — 0x0042b020/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_VA = 0x0042b020u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_VA_TRUE = 0x0042b061u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_VA_FALSE = 0x0042b067u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_EQ_IMM = 0xe8/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_LOW_BOUND = 0xccu/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_HIGH_BOUND = 0x1ebu/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_LOW_TABLE_VA = 0x0042b078u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B020_HIGH_TABLE_VA = 0x0042b150u/);
  /* Model constants agree (V23 mirror). */
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_VA, 0x0042b020);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_EQ_IMM, 0xe8);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_LOW_BOUND, 0xcc);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_HIGH_BOUND, 0x1eb);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_LOW_TABLE_BYTES, 205);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_HIGH_TABLE_BYTES, 492);
  /* Pinned tables must match the PE bytes exactly. */
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_BYTE_TABLE1.length, 205);
  assert.equal(ROOM_TRANSITION_ENGINE_42B020_BYTE_TABLE2.length, 492);
  const peByte = (va) => Buffer.from(peRaw(va, 1))[0];
  for (let i = 0; i < 205; i += 1) {
    assert.equal(ROOM_TRANSITION_ENGINE_42B020_BYTE_TABLE1[i],
                 peByte(0x0042b078 + i), `table1[${i}]`);
  }
  for (let i = 0; i < 492; i += 1) {
    assert.equal(ROOM_TRANSITION_ENGINE_42B020_BYTE_TABLE2[i],
                 peByte(0x0042b150 + i), `table2[${i}]`);
  }
  /* Export loads in the wasm module. */
  assert.equal(typeof api.contains42b020, "function");
  /* Raw disasm needles. */
  const dis = readFileSync(
    join(root, "output", "decomp", "5129df723e64", "section-notes",
         "rte-v23-42b020", "disasm-0042b020.txt"),
    "utf8");
  assert.match(dis, /cmp\s+eax, 0xe8/);
  assert.match(dis, /jg\s+0x42b047/);
  assert.match(dis, /je\s+0x42b061/);
  assert.match(dis, /jmp\s+dword ptr \[eax\*4 \+ 0x42b070\]/);
  assert.match(dis, /jmp\s+dword ptr \[eax\*4 \+ 0x42b148\]/);
});

test("v23 42b020: scalar laws (boundaries / both table paths / misses)", () => {
  const api = loadExports();
  /* je boundary: arg == 0xe8 -> TRUE regardless of tables. */
  assert.equal(api.contains42b020(0xe8) | 0, 1);
  assert.equal(roomTransitionEngine42b020Contains(0xe8) | 0, 1);
  /* SIGNED high-range hit: 0x3d6 (= 998) is max valid high arg. */
  assert.equal(api.contains42b020(0xe9) | 0,
               roomTransitionEngine42b020Contains(0xe9),
    "0xe9 wraps idx2 to 0xffffffff -> FALSE");
  assert.equal(api.contains42b020(0x3d6) | 0,
               roomTransitionEngine42b020Contains(0x3d6), "high top");
  /* low-range boundaries: -11 is the lowest valid low arg; -12 rejects. */
  assert.equal(api.contains42b020(-11) | 0,
               roomTransitionEngine42b020Contains(-11), "-11 edge");
  assert.equal(api.contains42b020(-12) | 0, 0, "-12 rejects (ja)");
  assert.equal(api.contains42b020(0xe7) | 0,
               roomTransitionEngine42b020Contains(0xe7), "0xe7 low top");
  /* misses on both paths. */
  assert.equal(api.contains42b020(0x7fffffff) | 0, 0, "huge positive miss");
});

test("v23 42b020: exhaustive + randomized differential corpus vs PE truth", () => {
  const api = loadExports();
  /* Independent PE-truth law computed from the section-table PE reader
     (NOT from the pinned arrays): exercises hexAt over both table VAs. */
  const peByte = (va) => Buffer.from(peRaw(va, 1))[0];
  const peTruth = (arg) => {
    const a = arg | 0;
    if (a === 0xe8) return 1;
    if (a > 0xe8) {
      const idx = ((a >>> 0) - 234) >>> 0;
      if (idx > 0x1eb) return 0;
      return peByte(0x0042b150 + idx) === 0 ? 1 : 0;
    }
    const idx = ((a >>> 0) - 11) >>> 0;
    if (idx > 0xcc) return 0;
    return peByte(0x0042b078 + idx) === 0 ? 1 : 0;
  };
  let cases = 0;
  /* exhaustive over every REACHABLE input plus miss margins */
  for (let a = -40; a <= 780; a += 1) {
    assert.equal(api.contains42b020(a | 0) | 0, peTruth(a), `exhaustive ${a}`);
    assert.equal(roomTransitionEngine42b020Contains(a | 0) | 0, peTruth(a),
      `exhaustive-model ${a}`);
    cases += 2;
  }
  /* randomized full-int32 misses */
  let seed = 0x0042b020 >>> 0;
  const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  for (let i = 0; i < 500; i++) {
    const a = rnd() | 0;
    assert.equal(api.contains42b020(a) | 0, peTruth(a), `rand ${i}`);
    cases += 1;
  }
  /* boundary pins: 0xe8 / 0xe9 / 0xe7 / -11 / -12 / 215 / 216 / 233 /
     234 / 725 / 726 */
  for (const b of [0xe6, 0xe7, 0xe8, 0xe9, 0xea, -13, -12, -11, -10,
                   214, 215, 216, 232, 233, 234, 235, 724, 725, 726]) {
    assert.equal(api.contains42b020(b | 0) | 0, peTruth(b), `boundary ${b}`);
    cases += 1;
  }
  assert.ok(cases >= 1800, `expected >= 1800 cases, got ${cases}`);
});
/* =====================================================================
 * v24 — PAIR: sibling switch classifiers 0x42b340 (186-entry table,
 * rebias 3, bound 0xb9) + 0x42b430 (24-entry table, rebias 0x13, bound
 * 0x17). Both FULLY PURE cdecl plain-ret bool-in-al. ZERO byte gates.
 * ===================================================================== */

test("v24 PAIR: build + ABI pin + census + table pins match the PE", () => {
  const api = loadExports();
  assert.equal(api.abi(), 30); // pre-flip
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  const h = readFileSync(header, "utf8");
  assert.match(h, /v24 — PAIR/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_VA = 0x0042b340u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_REBIAS = 3u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_BOUND = 0xb9u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_BYTE_TABLE_VA = 0x0042b374u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_TABLE_BYTES = 186u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B340_NEXT_FUNC = 0x0042b430u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B430_VA = 0x0042b430u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B430_REBIAS = 0x13u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B430_BOUND = 0x17u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42B430_TABLE_BYTES = 24u/);
  /* Model constants agree (V24 mirror). */
  assert.equal(ROOM_TRANSITION_ENGINE_42B340_VA, 0x0042b340);
  assert.equal(ROOM_TRANSITION_ENGINE_42B340_BOUND, 0xb9);
  assert.equal(ROOM_TRANSITION_ENGINE_42B340_TABLE_BYTES, 186);
  assert.equal(ROOM_TRANSITION_ENGINE_42B430_VA, 0x0042b430);
  assert.equal(ROOM_TRANSITION_ENGINE_42B430_BOUND, 0x17);
  assert.equal(ROOM_TRANSITION_ENGINE_42B430_TABLE_BYTES, 24);
  /* Pinned tables must match the PE bytes exactly. */
  assert.equal(ROOM_TRANSITION_ENGINE_42B340_BYTE_TABLE.length, 186);
  assert.equal(ROOM_TRANSITION_ENGINE_42B430_BYTE_TABLE.length, 24);
  const peByte = (va) => Buffer.from(peRaw(va, 1))[0];
  for (let i = 0; i < 186; i += 1) {
    assert.equal(ROOM_TRANSITION_ENGINE_42B340_BYTE_TABLE[i],
                 peByte(0x0042b374 + i), `tableA[${i}]`);
  }
  for (let i = 0; i < 24; i += 1) {
    assert.equal(ROOM_TRANSITION_ENGINE_42B430_BYTE_TABLE[i],
                 peByte(0x0042b460 + i), `tableB[${i}]`);
  }
  /* Both exports load in the wasm module. */
  for (const name of ["contains42b340", "contains42b430"]) {
    assert.equal(typeof api[name], "function", `export ${name}`);
  }
  /* Raw disasm needles (disasm-0042b340-0042b430.txt). */
  const dis = readFileSync(
    join(root, "output", "decomp", "5129df723e64", "section-notes",
         "rte-v24-42b340", "disasm-0042b340-0042b430.txt"),
    "utf8");
  assert.match(dis, /add\s+eax, -3/);
  assert.match(dis, /cmp\s+eax, 0xb9/);
  assert.match(dis, /ja\s+0x42b364/);
  assert.match(dis, /jmp\s+dword ptr \[eax\*4 \+ 0x42b36c\]/);
  assert.match(dis, /add\s+eax, -0x13/);
  assert.match(dis, /cmp\s+eax, 0x17/);
  assert.match(dis, /ja\s+0x42b452/);
  assert.match(dis, /jmp\s+dword ptr \[eax\*4 \+ 0x42b458\]/);
});

test("v24 PAIR: scalar laws (boundaries / table paths / misses)", () => {
  const api = loadExports();
  const peTruthA = (arg) => {
    const idx = (((arg | 0) >>> 0) - 3) >>> 0;
    if (idx > 0xb9) return 0;
    return ROOM_TRANSITION_ENGINE_42B340_BYTE_TABLE[idx] === 0 ? 1 : 0;
  };
  const peTruthB = (arg) => {
    const idx = (((arg | 0) >>> 0) - 0x13) >>> 0;
    if (idx > 0x17) return 0;
    return ROOM_TRANSITION_ENGINE_42B430_BYTE_TABLE[idx] === 0 ? 1 : 0;
  };
  /* A boundaries: rebias 3 -> lowest valid arg is 3; 2 rejects. */
  assert.equal(api.contains42b340(2) | 0, 0, "A: arg=2 rejects (ja)");
  assert.equal(api.contains42b340(3) | 0, peTruthA(3), "A: arg=3 lowest");
  assert.equal(api.contains42b340(3 + 0xb9) | 0, peTruthA(3 + 0xb9), "A: arg top");
  assert.equal(api.contains42b340(3 + 0xba) | 0, 0, "A: arg top+1 rejects");
  /* B boundaries: rebias 0x13 -> lowest valid arg is 0x13; 0x12 rejects. */
  assert.equal(api.contains42b430(0x12) | 0, 0, "B: arg=0x12 rejects (ja)");
  assert.equal(api.contains42b430(0x13) | 0, peTruthB(0x13), "B: arg=0x13 lowest");
  assert.equal(api.contains42b430(0x13 + 0x17) | 0, peTruthB(0x13 + 0x17), "B: arg top");
  assert.equal(api.contains42b430(0x13 + 0x18) | 0, 0, "B: arg top+1 rejects");
  /* wide misses never match a signed misread. */
  for (const v of [0x80000000, 0xffffffff, 0x7fffffff]) {
    assert.equal(api.contains42b340(v >>> 0) | 0, 0, `A wide miss ${v}`);
    assert.equal(api.contains42b430(v >>> 0) | 0, 0, `B wide miss ${v}`);
  }
});

