/* =====================================================================
 * v32 — POST: value+8 getter (6B) + ne-check (17B). Both FULLY PURE.
 * ===================================================================== */

test("v32: build + ABI pin + census", () => {
  const api = loadExports();
  assert.equal(api.abi(), 30); // pre-flip
  assert.equal(ROOM_TRANSITION_ENGINE_PURE_ABI_VERSION, 30);
  const h = readFileSync(header, "utf8");
  assert.match(h, /v32 — POST/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C700_VA = 0x0042c700u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C700_BODY_BYTES = 6u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C700_CALLSITE_COUNT = 5/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C700_ADD_IMM = 8u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C710_BODY_BYTES = 17u/);
  assert.match(h, /ISAAC_ROOM_TRANSITION_ENGINE_42C710_CALLSITE_COUNT = 25/);
  for (const name of ["plus842c700", "neCheck42c710"]) {
    assert.equal(typeof api[name], "function", `export ${name}`);
  }
  assert.equal(ROOM_TRANSITION_ENGINE_42C700_VA, 0x0042c700);
  assert.equal(ROOM_TRANSITION_ENGINE_42C700_ADD_IMM, 8);
  assert.equal(ROOM_TRANSITION_ENGINE_42C710_CALLSITE_COUNT, 25);
});

test("v32: scalar laws (value+8 / ne-check)", () => {
  const api = loadExports();
  /* value+8: u32-wrapping add of 8 to the loaded dword.
     Write test data into wasm linear memory, call with pointers. */
  const view = new DataView(api.memory.buffer);
  const BASE = MEM + 0x30000;
  for (const v of [0, 1, 8, 0xfffffff8, 0xfffffff9, 0x7fffffff, 0x80000000]) {
    view.setUint32(BASE, v >>> 0, true);
    assert.equal(api.plus842c700(BASE) >>> 0,
                 roomTransitionEngine42c700ValuePlus8({ mem: new Uint8Array(view.buffer), thisOff: BASE }) >>> 0,
      `plus8 lockstep v=${v}`);
    assert.equal(api.plus842c700(BASE) >>> 0, (v + 8) >>> 0,
      `plus8 exact v=${v}`);
  }
  /* ne-check: [this+0] != [*other] -> 1; equality -> 0. */
  /* ne-check: [this+0] != [*other] -> 1; equality -> 0.
     Write distinct values at two separate arena addresses. */
  const NE_BASE = MEM + 0x31000;
  view.setUint32(NE_BASE + 0x00, 0x11111111, true);
  view.setUint32(NE_BASE + 0x40, 0x22222222, true);
  assert.equal(api.neCheck42c710(0, NE_BASE, NE_BASE + 0x40) | 0, 1,
    "ne different");
  assert.equal(api.neCheck42c710(0, NE_BASE + 0x40, NE_BASE + 0x40) | 0, 0,
    "ne same");
});

test("v32: randomized differential corpus (500 draws)", () => {
  const api = loadExports();
  const view = new DataView(api.memory.buffer);
  const R = MEM + 0xfc000;
  let seed = 0x0042c700 >>> 0;
  const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  let cases = 0;
  for (let i = 0; i < 500; i++) {
    const v = rnd() >>> 0;
    const a = rnd() >>> 0;
    const b = rnd() >>> 0;
    view.setUint32(R + 0, v, true);
    view.setUint32(R + 0x40, a, true);
    view.setUint32(R + 0x80, b, true);
    const wP = api.plus842c700(R) >>> 0;
    const jP = roomTransitionEngine42c700ValuePlus8({ mem: new Uint8Array(view.buffer), thisOff: R }) >>> 0;
    assert.equal(wP, (v + 8) >>> 0, `trial ${i} plus8-wasm`);
    assert.equal(jP, (v + 8) >>> 0, `trial ${i} plus8-model`);
    const wN = api.neCheck42c710(0, R + 0x40, R + 0x80) | 0;
    const m3 = new Uint8Array(view.buffer);
    const jN = roomTransitionEngine42c710NeCheck({ mem: m3, thisOff: R + 0x40, otherOff: R + 0x80 }) | 0;
    assert.equal(wN, jN, `ne ${i}`);
    cases += 2;
  }
  assert.ok(cases >= 1000, `expected >= 1000 cases, got ${cases}`);
});
