test("v34: scalar laws (base + index*4 u32 wrap)", () => {
  const api = loadExports();
  const model = roomTransitionEngine42c810ElemAddr;
  /* directed: boundary values */
  for (const [b, i] of [[0, 0], [0x1000, 0], [0x1000, 1],
                         [0x1000, 100], [0xfffffff8, 2]]) {
    const wV = api.elemAddr42c810(b >>> 0, i >>> 0) >>> 0;
    const jV = model(b >>> 0, i >>> 0) >>> 0;
    assert.equal(wV, jV, `addr b=${b} idx=${i}`);
    assert.equal(wV, ((b >>> 0) + (i >>> 0) * 4) >>> 0,
      `addr-exact b=${b} idx=${i}`);
  }
  /* u32 wrap: base near max */
  assert.equal(api.elemAddr42c810(0xfffffffc, 1) >>> 0, 0,
    "wrap: 0xfffffffc + 4 = 0");
});

test("v34: randomized differential corpus (500 draws)", () => {
  const api = loadExports();
  let seed = 0x0042c810 >>> 0;
  const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed; };
  let cases = 0;
  for (let i = 0; i < 500; i++) {
    const base = rnd() >>> 0;
    const index = rnd() >>> 0;
    const wV = api.elemAddr42c810(base, index) >>> 0;
    const jV = roomTransitionEngine42c810ElemAddr(base, index) >>> 0;
    assert.equal(wV, jV, `trial ${i} lockstep`);
    cases += 1;
  }
  assert.ok(cases >= 500, `expected >= 500 cases, got ${cases}`);
});

