test("v35: scalar laws (conditional fallback)", () => {
  const api = loadExports();
  /* primary nonzero -> return primary */
  for (const [p, f] of [[1, 100], [5, 200], [0x7fffffff, 300]]) {
    assert.equal(api.condGet42d040(p >>> 0, f >>> 0) >>> 0,
                 p >>> 0, `primary p=${p}`);
  }
  /* primary zero -> return fallback */
  assert.equal(api.condGet42d040(0, 100) >>> 0, 100, "fallback f=100");
  assert.equal(api.condGet42d040(0, 0xffffffff) >>> 0, 0xffffffff,
    "fallback f=max");
});
